// Notebook — Gtk.Notebook
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles notebook with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { PositionType } from "@/lib/enums"

export interface NotebookProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.Notebook */
  enablePopup?: boolean

  /** utf8, from Gtk.Notebook */
  groupName?: string

  /** gint, from Gtk.Notebook */
  page?: number

  /** gboolean, from Gtk.Notebook */
  scrollable?: boolean

  /** gboolean, from Gtk.Notebook */
  showBorder?: boolean

  /** gboolean, from Gtk.Notebook */
  showTabs?: boolean

  /** PositionType, from Gtk.Notebook */
  tabPos?: PositionType
}

export function Notebook({ className, children }: NotebookProps) {
  return (
    <div className={cn("duration-[300ms]", className)}>
      {children}
    </div>
  )
}
